  <header className="presenter-menubar"><strong>SLC Presenter</strong><nav><button onClick={()=>setFileMenuOpen(value=>!value)}>File</button><button onClick={()=>openSettings('Appearance')}>View</button><button onClick={()=>openSettings('General')}>Settings</button>{fileMenuOpen&&<div className="file-menu"><button onClick={()=>{setFileMenuOpen(false);newSchedule()}}><Icon name="new"/>New service <kbd>Ctrl+N</kbd></button><button onClick={()=>{setFileMenuOpen(false);openSchedule()}}><Icon name="open"/>Open service <kbd>Ctrl+O</kbd></button><button onClick={()=>{setFileMenuOpen(false);saveSchedule()}}><Icon name="save"/>Save service <kbd>Ctrl+S</kbd></button><button onClick={()=>{setFileMenuOpen(false);saveSchedule(true)}}><Icon name="save"/>Save As…</button><hr/><button onClick={()=>{setFileMenuOpen(false);importLibrary()}}><Icon name="import"/>Import presentation database…</button><button onClick={()=>{setFileMenuOpen(false);importBible()}}><Icon name="import"/>Import Bible translation…</button></div>}</nav>{window.slcPrototype&&<span className="prototype-badge">UI Prototype · Browser storage</span>}</header>
