function Content({item,active,inspect,go,live}){return <div className="upper-content">{item?.type==='Media'?<div className={`media-preview-card ${item.missing?'missing':''}`}><Thumb item={item}/><strong>{item.missing?'⚠ ':''}{item.title}</strong><small>{item.missing?'The source file is unavailable.':item.mediaKind||item.mediaType}</small></div>:<div className={`slide-list ${live?'live-slides':''}`}>{(item?.slides||[]).map((s,i)=><button key={`${s.name}-${i}`} className={active?.activeSlide?.name===s.name?'selected':''} onClick={()=>inspect(item,s)} onDoubleClick={()=>go({...item,activeSlide:s})}><b>{s.name}</b><span>{s.text}</span></button>)}</div>}</div>}
function OutputSettings({outputs,displays,modes,onMode,enable,disable,configure}){return <div className="outputs-popover output-quick-panel"><header><strong>Outputs</strong><small>Live controls</small></header>{outputs.map(output=><section key={output.id} className={output.status==='error'?'error':''}><div><strong>{output.name}</strong><span title={output.lastError||''}>{output.status==='error'?'⚠ Error':output.status==='starting'?'◌ Starting':output.enabled?'● Active':'○ Disabled'}</span></div><small>{output.transport.type==='ndi'?'NDI · unavailable':output.transport.type==='network'?'SLC Network Output':displays.find(display=>display.id===output.transport.display.destinationId)?.label||'Display not selected'}</small><div className="output-actions"><button className={modes[output.id]==='clear'?'active':''} onClick={()=>onMode(output.id,'clear')}>Clear</button><button className={modes[output.id]==='black'?'active':''} onClick={()=>onMode(output.id,'black')}>Black</button><button onClick={()=>enable(output)} disabled={output.transport.type==='ndi'}>{output.enabled?'Restart':'Start'}</button><button onClick={()=>disable(output)} disabled={!output.enabled}>Stop</button></div></section>)}<button className="output-settings-link" onClick={()=>configure(null)}>Output Settings…</button></div>}
function AiAssistPanel({books,translation,onPreview}){const[topic,setTopic]=useState(''),[suggestions,setSuggestions]=useState([]),[history,setHistory]=useState([]),[pinned,setPinned]=useState([]),[status,setStatus]=useState(null),[busy,setBusy]=useState(false),[message,setMessage]=useState('Checking local AI…'),service=useRef(new ScriptureSuggestionService()),prefs=readPresenterSettings();const refresh=async()=>{try{const value=await window.slcDesktop?.localAiStatus?.(prefs.aiModel||'gemma3:1b');setStatus(value||{runtime:'unavailable',modelReady:false});setMessage(value?.modelReady?'Local AI ready':value?.runtime==='ready'?'Model not installed · using local Bible search':'Ollama unavailable · using local Bible search')}catch(error){setStatus({runtime:'unavailable',modelReady:false});setMessage(`Local Bible search · ${error.message}`)}};useEffect(()=>{refresh()},[]);const validate=async items=>{const checked=[];for(const item of items){const verses=await window.slcDesktop?.listBibleVerses?.(translation,item.book,item.chapter)||[],selected=verses.filter(verse=>verse.verse>=item.startVerse&&verse.verse<=item.endVerse);if(selected.length===item.endVerse-item.startVerse+1)checked.push({...item,reason:item.reason||item.transcriptEvidence||selected.map(verse=>verse.text).join(' ')})}return checked};const analyse=async()=>{if(!topic.trim()||busy)return;setBusy(true);setMessage('Finding relevant passages…');try{let found=[],source='local';if(status?.modelReady&&window.slcDesktop?.localAiSuggest){found=await window.slcDesktop.localAiSuggest({topic,model:prefs.aiModel||'gemma3:1b',books});source='ollama'}else{found=service.current.ingest(topic,books);if(!found.length)found=await window.slcDesktop?.searchBible?.(translation,topic,8)||[]}found=await validate(found);setSuggestions(current=>[...found,...current.filter(item=>!found.some(next=>next.id===item.id))].slice(0,8));setHistory(current=>[...found,...current].slice(0,20));setMessage(found.length?`${found.length} locally verified suggestion${found.length===1?'':'s'} · ${source==='ollama'?'Gemma 3':'Bible search'}`:'No verified passages found. Try different wording.')}catch(error){const fallback=await validate(await window.slcDesktop?.searchBible?.(translation,topic,8)||[]);setSuggestions(fallback);setMessage(fallback.length?`Local AI was unavailable; showing ${fallback.length} Bible search result${fallback.length===1?'':'s'}.`:error.message)}finally{setBusy(false)}};const load=item=>{onPreview(item);setHistory(current=>[{...item,timestamp:Date.now()},...current.filter(entry=>entry.id!==item.id)].slice(0,20))},labels={ai_suggestion:'Local AI',explicit_reference:'Explicit reference',direct_quote:'Direct quote',likely_match:'Likely match',related:'Related',local_search:'Local Bible search'};return <div className="ai-assist"><header><div><strong>AI Scripture Assist</strong><span className={`ai-state ${status?.modelReady?'':'unavailable'}`}>{status?.modelReady?'● Local AI ready':'○ Local search fallback'}</span></div><span className="ai-provider">{message}</span><nav><button onClick={refresh} disabled={busy}>Test</button>{busy&&<button onClick={()=>window.slcDesktop?.cancelLocalAi?.()}>Cancel</button>}</nav></header><section className="ai-transcript"><strong>Sermon topic or sentence</strong><p>Suggestions stay private until you select one. Verse text always comes from the installed Bible.</p><textarea value={topic} onChange={event=>setTopic(event.target.value)} placeholder="Example: God’s grace is sufficient in weakness" onKeyDown={event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();analyse()}}}/><button onClick={analyse} disabled={!topic.trim()||busy}>{busy?'Searching…':'Suggest Scriptures'}</button></section><main><section className="ai-suggestions"><h3>Suggested Scriptures</h3>{suggestions.length?suggestions.map(item=><article key={item.id} onClick={()=>load(item)}><header><strong>{item.reference}</strong><em className={item.confidence}>{item.confidence.toUpperCase()}</em></header><p>{item.reason||item.transcriptEvidence}</p><footer><span>{labels[item.detectionType]||'Verified suggestion'}</span><time>{new Date(item.timestamp).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</time><button onClick={event=>{event.stopPropagation();setPinned(current=>current.some(entry=>entry.id===item.id)?current.filter(entry=>entry.id!==item.id):[item,...current])}}>📌</button><button onClick={event=>{event.stopPropagation();setSuggestions(current=>current.filter(entry=>entry.id!==item.id))}}>Dismiss</button></footer></article>):<div className="ai-empty">Enter a topic to receive locally verified references. Nothing is sent to Preview or Live automatically.</div>}</section><aside><h3>Pinned</h3>{pinned.map(item=><button key={item.id} onClick={()=>load(item)}>📌 {item.reference}</button>)}<h3>Recent</h3>{history.map((item,index)=><button key={`${item.id}-${index}`} onClick={()=>load(item)}><time>{new Date(item.timestamp).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time>{item.reference}</button>)}</aside></main></div>}
function Canvas({title,item,black,clear,playback,controlVideo,onProgress}){const slide=item?.activeSlide||item?.slides?.[0],transparent=resolveSceneBackground(item,slide,item?.theme?.background||fallbackTheme.background).type==='transparent';return <div className={`canvas-zone ${item?.mediaType==='Video'?'has-video-controls':''} ${transparent?'inspect-transparent':''}`}><span>{title}</span><Output item={item} black={black} clear={clear} playback={playback} onProgress={onProgress}/>{item?.mediaType==='Video'&&controlVideo&&<VideoControls playback={playback} control={controlVideo}/>}</div>}
function VideoControls({playback,control}){const duration=Math.max(0,playback.duration||0),position=Math.min(duration||Infinity,Math.max(0,playback.position||0));return <div className="video-controls"><button onClick={()=>control({playing:!playback.playing})}>{playback.playing?'❚❚ Pause':'▶ Play'}</button><button onClick={()=>control({playing:false,position:0})}>■ Stop</button><button onClick={()=>control({playing:true,position:0})}>↻ Restart</button><span>{formatTime(position)}</span><input className="video-scrubber" type="range" min="0" max={duration||1} step="0.05" value={position} onChange={event=>control({position:Number(event.target.value)})} aria-label="Video position"/><span>{formatTime(duration)}</span><label>Volume<input type="range" min="0" max="1" step="0.05" value={playback.volume} onChange={event=>control({volume:Number(event.target.value)})}/></label><button className={playback.muted?'active':''} onClick={()=>control({muted:!playback.muted})}>{playback.muted?'Unmute':'Mute'}</button><button className={playback.loop?'active':''} onClick={()=>control({loop:!playback.loop})}>Loop</button></div>}
function Sidebar({tab,count,translations=[],translation,setTranslation,recent=[],onRecent,mediaCounts={},mediaFilter,setMediaFilter}){if(tab==='Scriptures')return <aside className="library-sidebar scripture-sidebar"><strong>TRANSLATIONS</strong>{translations.map(item=><button className={item.id===translation?'selected':''} key={item.id} onClick={()=>setTranslation(item.id)}><span className="translation-code">{item.code}</span><small>{item.name}</small></button>)}<strong>RECENT</strong>{recent.length?recent.map(item=><button key={item} onClick={()=>onRecent(item)}>{item}</button>):<p>No references yet</p>}</aside>;if(tab==='Media'){const entries=[['All Media',mediaCounts.all||0],['Videos',mediaCounts.videos||0],['Images',mediaCounts.images||0]];return <aside className="library-sidebar">{entries.map(([name,total])=><button className={mediaFilter===name?'selected':''} key={name} onClick={()=>setMediaFilter(name)}>{name}<span>{total}</span></button>)}</aside>}const names=tab==='Songs'?['All Songs','Favorites']:tab==='Themes'?['All themes','Songs','Scripture','Presentations']:['All items','Favorites'];return <aside className="library-sidebar">{names.map((x,i)=><button className={i===0?'selected':''} key={x}>{x}<span>{i===0?count:''}</span></button>)}</aside>}
function MatchText({text,range}){if(!range)return text;return <>{text.slice(0,range.start)}<mark>{text.slice(range.start,range.end)}</mark>{text.slice(range.end)}</>}
function SongTable({items,selected,inspect,onMenu,onDrag,searching,activeIndex,onActivate}){return <div className={`library-table song-results ${searching?'searching':''}`}><div className="table-head"><span>Title</span><span>{searching?'Author / matching lyric':'Details'}</span><span>{searching?'Match':'Source'}</span></div>{items.map((x,index)=><button key={x.id} draggable onDragStart={event=>onDrag(event,x)} className={`${selected?.id===x.id?'selected':''} ${activeIndex===index&&searching?'keyboard-active':''}`} onMouseEnter={()=>onActivate(index)} onClick={()=>{onActivate(index);inspect(x)}} onContextMenu={event=>onMenu(event,x)}><strong>{x.title}</strong><span className="song-result-detail">{searching&&x.matchText?<small>{x.author}</small>:null}{searching&&x.matchText?<em><MatchText text={x.matchText} range={x.highlight}/></em>:<>{x.detail}</>}</span><span className={x.matchKind==='lyric'?'lyric-match':''}>{searching?x.matchKind==='lyric'?'Lyric match':x.matchKind==='title'?'Title match':'Author match':'Local library'}</span></button>)}{searching&&!items.length&&<div className="no-song-results"><strong>No matching songs</strong><span>Try another title, author, or lyric phrase.</span></div>}</div>}
function BibleBrowser({books,book,setBook,chapter,setChapter,verses,picked,setPicked,reference,setReference,resolveReference,liveVerse,message,inputRef}){const[mode,setMode]=useState('library'),[unread,setUnread]=useState(0),selectedBook=books.find(item=>item.book===book),chapters=Array.from({length:selectedBook?.chapters||0},(_,index)=>index+1),anchor=useRef(null),verseListRef=useRef(null),translation=localStorage.getItem('slc-scripture-translation')||readPresenterSettings().defaultTranslation;useEffect(()=>{if(!picked.length)return;verseListRef.current?.querySelector(`[data-verse="${picked[0]}"]`)?.scrollIntoView({block:'nearest'})},[picked]);const selectVerse=(event,number)=>{setPicked(current=>{if(event.shiftKey&&anchor.current!=null){const start=Math.min(anchor.current,number),end=Math.max(anchor.current,number);return verses.filter(item=>item.verse>=start&&item.verse<=end).map(item=>item.verse)}anchor.current=number;if(event.ctrlKey||event.metaKey)return current.includes(number)?current.filter(item=>item!==number):[...current,number].sort((a,b)=>a-b);return[number]})};return <div className="scripture-workspace"><nav className="scripture-mode-tabs"><button className={mode==='library'?'active':''} onClick={()=>setMode('library')}>Scripture Library</button><button className={mode==='assist'?'active':''} onClick={()=>{setMode('assist');setUnread(0)}}>● AI Assist{unread?` ${unread}`:''}</button>{mode==='library'&&<form className="scripture-reference-inline" onSubmit={event=>{event.preventDefault();resolveReference(reference,{previewResult:true})}}><Icon name="search"/><input ref={inputRef} value={reference} onChange={event=>setReference(event.target.value)} placeholder="Reference, e.g. Romans 8:28–31" aria-label="Scripture reference"/>{message==='Reference not found.'&&<span>Reference not found</span>}</form>}</nav>{mode==='assist'?<AiAssistPanel books={books} translation={translation} onSuggestion={()=>mode!=='assist'&&setUnread(value=>value+1)} onPreview={item=>resolveReference(`${item.book} ${item.chapter}:${item.startVerse}${item.endVerse!==item.startVerse?`-${item.endVerse}`:''}`,{previewResult:true})}/>:<div className="bible-browser"><div className="scripture-browser-columns"><div className="book-list">{books.map(item=><button className={item.book===book?'selected':''} key={item.book} onClick={()=>{setBook(item.book);setChapter(1)}}>{item.book}</button>)}</div><div className="chapter-list">{chapters.map(number=><button className={number===chapter?'selected':''} key={number} onClick={()=>setChapter(number)}>{number}</button>)}</div><div className="verse-list" ref={verseListRef}>{verses.map(item=><button data-verse={item.verse} key={item.verse} className={picked.includes(item.verse)?'selected':''} onClick={event=>selectVerse(event,item.verse)} onDoubleClick={()=>liveVerse(item)}><b>{item.verse}</b><span>{item.text}</span></button>)}</div></div><div className="scripture-actions"><span>{picked.length?`${picked.length} verse${picked.length===1?'':'s'} selected${reference?` · ${reference}`:''}`:`${book} ${chapter} · select verse${verses.length===1?'':'s'} to update Preview`}</span></div></div>}</div>}
function Scriptures({items,picked,setPicked,inspect,go,preview}){return <div className="scripture-browser"><div className="book-list">{['Genesis','Exodus','Leviticus','Numbers','Deuteronomy','Joshua','Judges','Ruth','1 Samuel','Manual'].map((x,i)=><button className={i===0?'selected':''} key={x}>{x}</button>)}</div><div className="chapter-list">{Array.from({length:12},(_,i)=><button className={i===0?'selected':''} key={i}>{i+1}</button>)}</div><div className="verse-list">{items.map((v,i)=><button key={v.id} className={picked.includes(v.id)?'selected':''} onClick={()=>{if(v.databaseId)inspect(v);else setPicked(c=>c.includes(v.id)?c.filter(id=>id!==v.id):[...c,v.id])}} onDoubleClick={()=>go({...v,activeSlide:v.slides?.[0]})}><b>{i+1}</b><span>{v.text||v.slides?.[0]?.text}</span></button>)}</div><button className="preview-selection" onClick={preview}>Preview selected verses</button></div>}
