function DocumentEditor({value,media=[],onCancel,onSave}){const[draft,setDraft]=useState(value),[active,setActive]=useState(0),field=(name,next)=>setDraft(current=>({...current,[name]:next})),current=draft.slides[active]||draft.slides[0],slideField=(name,next)=>field('slides',draft.slides.map((slide,index)=>index===active?{...slide,[name]:next}:slide)),move=direction=>{const target=active+direction;if(target<0||target>=draft.slides.length)return;const slides=[...draft.slides],[item]=slides.splice(active,1);slides.splice(target,0,item);field('slides',slides);setActive(target)},add=()=>{field('slides',[...draft.slides,{name:`Slide ${draft.slides.length+1}`,title:'',body:'',text:'',reference:'',imageMediaId:'',imageUrl:'',imageFit:'fit',background:{type:'solid',color:'#000000'}}]);setActive(draft.slides.length)},duplicate=()=>{const slides=[...draft.slides];slides.splice(active+1,0,{...current,name:`${current.name} Copy`});field('slides',slides);setActive(active+1)},remove=()=>{if(draft.slides.length===1)return;field('slides',draft.slides.filter((_,index)=>index!==active));setActive(Math.max(0,active-1))},chooseImage=(fieldName,id)=>{const item=media.find(entry=>entry.databaseId===id);slideField(fieldName,id);slideField(fieldName==='imageMediaId'?'imageUrl':'background',fieldName==='imageMediaId'?(item?`/media/${item.databaseId}`:''):(item?{type:'image',mediaId:item.databaseId,url:`/media/${item.databaseId}`,fit:'cover',position:'center'}:{type:'solid',color:'#000000'}))};return <div className="editor-backdrop"><form className="presentation-editor" onSubmit={event=>{event.preventDefault();onSave({...draft,reference:draft.kind==='Scripture'?draft.title:draft.reference,slides:draft.slides.map(slide=>({...slide,text:[slide.title,slide.body].filter(Boolean).join('\n')||slide.text,reference:draft.kind==='Scripture'?draft.title:''}))})}}><header><div><strong>{draft.id?'Edit':'New'} {draft.kind==='Scripture'?'Scripture':'Presentation'}</strong><span>Build reusable native slides for Preview and Live</span></div><button type="button" onClick={onCancel}>×</button></header><div className="presentation-meta"><label>{draft.kind==='Scripture'?'Scripture reference':'Presentation title'}<input autoFocus value={draft.title} onChange={event=>field('title',event.target.value)} required/></label><label>Alignment<select value={draft.alignment} onChange={event=>field('alignment',event.target.value)}><option value="left">Left</option><option value="center">Centre</option><option value="right">Right</option></select></label></div><aside><div><strong>Slides</strong><button type="button" onClick={add}>＋</button></div>{draft.slides.map((slide,index)=><button type="button" className={index===active?'active':''} key={index} onClick={()=>setActive(index)}><b>{index+1}</b><span><strong>{slide.name}</strong><small>{slide.title||slide.body||slide.text||'Image slide'}</small></span></button>)}</aside><main><div className="presentation-slide-tools"><button type="button" onClick={()=>move(-1)} disabled={!active}>↑ Move</button><button type="button" onClick={()=>move(1)} disabled={active===draft.slides.length-1}>↓ Move</button><button type="button" onClick={duplicate}>⧉ Duplicate</button><button type="button" onClick={remove} disabled={draft.slides.length===1}>× Delete</button></div><div className="presentation-fields"><label>Slide name<input value={current.name} onChange={event=>slideField('name',event.target.value)}/></label><label>Title<input value={current.title||''} onChange={event=>slideField('title',event.target.value)} placeholder="Optional heading"/></label><label className="wide">Body<textarea value={current.body??current.text??''} onChange={event=>slideField('body',event.target.value)} placeholder="Slide text"/></label><label>Optional image<select value={current.imageMediaId||''} onChange={event=>chooseImage('imageMediaId',event.target.value)}><option value="">No image</option>{media.map(item=><option key={item.databaseId} value={item.databaseId}>{item.title}</option>)}</select></label><label>Image fit<select value={current.imageFit||'fit'} onChange={event=>slideField('imageFit',event.target.value)}><option value="fit">Fit</option><option value="fill">Fill</option></select></label><label>Background<select value={current.background?.type||'solid'} onChange={event=>slideField('background',event.target.value==='image'?{type:'image',url:'',fit:'cover'}:{type:'solid',color:current.background?.color||'#000000'})}><option value="solid">Solid colour</option><option value="image">Library image</option></select></label>{current.background?.type==='solid'?<label>Background colour<input type="color" value={current.background?.color||'#000000'} onChange={event=>slideField('background',{type:'solid',color:event.target.value})}/></label>:<label>Background image<select value={current.background?.mediaId||''} onChange={event=>chooseImage('background',event.target.value)}><option value="">Choose image</option>{media.map(item=><option key={item.databaseId} value={item.databaseId}>{item.title}</option>)}</select></label>}</div></main><footer><span>{draft.slides.length} slide{draft.slides.length===1?'':'s'}</span><button type="button" onClick={onCancel}>Cancel</button><button className="primary" type="submit" disabled={!draft.title.trim()}>Save Presentation</button></footer></form></div>}
function PreServiceCheck({value,onRefresh,onClose,onOutputs}){return <div className="editor-backdrop"><section className="pre-service-check"><header><div><strong>Pre-Service Check</strong><span>{value.ready?'Ready for service':`${value.errors||0} error${value.errors===1?'':'s'} · ${value.warnings||0} warning${value.warnings===1?'':'s'}`}</span></div><button onClick={onClose}>×</button></header><main>{value.checks.map(item=><article className={item.ok?'ready':item.severity==='error'?'error':'warning'} key={item.label}><b>{item.ok?'✓':item.severity==='error'?'×':'!'}</b><div><strong>{item.label}</strong><small>{item.detail}</small></div></article>)}</main><footer><span>Checked {value.checkedAt.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span><button onClick={onOutputs}>Output Settings</button><button onClick={onRefresh}>Run Again</button><button className="primary" onClick={onClose}>Close</button></footer></section></div>}
function SongEditor({value,onCancel,onSave}){const[draft,setDraft]=useState(value),field=(name,value)=>setDraft(current=>({...current,[name]:value})),section=(index,name,value)=>field('sections',draft.sections.map((item,i)=>i===index?{...item,[name]:value}:item)),move=(index,direction)=>{const target=index+direction;if(target<0||target>=draft.sections.length)return;const next=[...draft.sections],[item]=next.splice(index,1);next.splice(target,0,item);field('sections',next)};return <div className="editor-backdrop"><form className="song-editor" onSubmit={event=>{event.preventDefault();onSave(draft)}}><header><strong>{draft.id?'Edit song':'New song'}</strong><button type="button" onClick={onCancel}>×</button></header><div className="song-fields"><label>Title<input autoFocus value={draft.title} onChange={e=>field('title',e.target.value)} required/></label><label>Alternate title<input value={draft.alternate_title} onChange={e=>field('alternate_title',e.target.value)}/></label><label>Author<input value={draft.author} onChange={e=>field('author',e.target.value)}/></label><label>CCLI number<input value={draft.ccli_number} onChange={e=>field('ccli_number',e.target.value)}/></label><label className="wide">Copyright<input value={draft.copyright} onChange={e=>field('copyright',e.target.value)}/></label></div><div className="section-editor"><div className="section-editor-heading"><strong>Song sections</strong><button type="button" onClick={()=>field('sections',[...draft.sections,{label:`Verse ${draft.sections.length+1}`,text:''}])}>＋ Add section</button></div>{draft.sections.map((item,index)=><article key={index}><input aria-label="Section name" value={item.label} onChange={e=>section(index,'label',e.target.value)}/><div><button type="button" onClick={()=>move(index,-1)} disabled={!index}>↑</button><button type="button" onClick={()=>move(index,1)} disabled={index===draft.sections.length-1}>↓</button><button type="button" onClick={()=>field('sections',draft.sections.filter((_,i)=>i!==index))} disabled={draft.sections.length===1}>×</button></div><textarea aria-label={`${item.label} lyrics`} value={item.text} onChange={e=>section(index,'text',e.target.value)} placeholder="Enter lyrics. Use line breaks exactly as they should appear on screen." required/></article>)}</div><footer><button type="button" onClick={onCancel}>Cancel</button><button className="primary" type="submit">Save song</button></footer></form></div>}
